import{TenBase,fmt,svgEl}from'./ten-base.js';import{area,dist,angle,clamp}from'../math.js';import{rad,trig,tangents,sector}from'../ten-math.js';
export default class TenGeometry extends TenBase{
 constructor(host,ctx){super(host,ctx);if(this.id===6)this.points=this.mode==='similarity'?[[-6,-2],[-3,-2],[-5,1]]:[[-3,3],[-6,-2],[1,-2]];this.draw()}
 move(i,p){if(this.id===6)this.points[i]=[clamp(p[0],-7,7),clamp(p[1],-4.5,4.5)]}
 draw(){this.clear(false);let v=this.v,m=this.mode,s=(en,hi)=>this.say(en,hi);
 if(this.id===6){let[A,B,C]=this.points;this.path([A,B,C],'shape',true);this.points.forEach((p,i)=>this.point(p,i,['A','B','C'][i]));if(area(this.points)<.01){this.report([s('The vertices are nearly collinear. Move a vertex to form a triangle.','शीर्ष लगभग एक रेखा में हैं। त्रिभुज बनाने के लिए शीर्ष खिसकाएँ।')]);return}if(m==='similarity'){let k=v,D=[1,-2],E=[1+(B[0]-A[0])*k,-2+(B[1]-A[1])*k],F=[1+(C[0]-A[0])*k,-2+(C[1]-A[1])*k];this.path([D,E,F],'gold',true);[D,E,F].forEach((p,i)=>this.mark(p,['D','E','F'][i]));let sides=[dist(A,B),dist(B,C),dist(C,A)],angles=[angle(B,A,C),angle(A,B,C),angle(A,C,B)];this.report([`k = ${v}; DE/AB = EF/BC = FD/CA = ${v}`,`AB, BC, CA = ${sides.map(fmt).join(', ')}`,`DE, EF, FD = ${sides.map(x=>fmt(x*k)).join(', ')}`,`${s('Corresponding angles','संगत कोण')}: ${angles.map(fmt).join('°, ')}°`],['Equal corresponding angles and proportional corresponding sides establish similarity.','संगत कोण बराबर और संगत भुजाएँ समानुपाती होने से समरूपता मिलती है।']);return}
 let t=m==='converse'?.5:v,u=v,D=A.map((x,i)=>x+t*(B[i]-x)),E=A.map((x,i)=>x+u*(C[i]-x)),parallel=Math.abs(t-u)<1e-8;this.line(D,E,parallel?'gold':'shape',{'stroke-dasharray':parallel?'0':'6 4'});this.mark(D,'D');this.mark(E,'E');this.report([`AD / AB = ${fmt(t)}; AE / AC = ${fmt(u)}`,`AD / DB = ${fmt(t/(1-t))}; AE / EC = ${fmt(u/(1-u))}`,parallel?'DE ∥ BC':s('DE is not parallel to BC.','DE, BC के समांतर नहीं है।')],['The division fractions must be equal; both points must lie on the corresponding sides.','विभाजन के भिन्न बराबर हों; दोनों बिंदु संगत भुजाओं पर होने चाहिए।']);return}
 if(this.id===8){let theta=m==='standard'?[0,30,45,60,90][v]:v,q=trig(theta),x=5*q.cos,y=5*q.sin;if(m==='identity'){this.circle([0,0],3,'shape');this.line([-3.5,0],[3.5,0],'axis');this.line([0,-.3],[0,3.5],'axis');this.path([[0,0],[3*q.cos,0],[3*q.cos,3*q.sin]],'gold',true);this.mark([3*q.cos,3*q.sin],`(${fmt(q.cos)}, ${fmt(q.sin)})`);this.text([3.1,-.4],'1');this.text([-.5,3],'1');this.text([-2,-1],s('Unit circle (enlarged)','इकाई वृत्त (बड़ा करके)'))}else{this.path([[-3,-2],[-3+x,-2],[-3+x,-2+y]],'shape',true);this.text([-3+x/2,-2.5],`5 cos θ = ${fmt(x)}`);this.text([-2.7+x,-2+y/2],`5 sin θ = ${fmt(y)}`);this.text([-3+x/2,-1.7+y/2],'5');this.text([-3.5,-1.5],`θ = ${theta}°`)}let val=x=>x===null?s('Undefined','अपरिभाषित'):fmt(x);this.report([`θ = ${theta}°`,`sin θ = ${val(q.sin)}; cos θ = ${val(q.cos)}; tan θ = ${val(q.tan)}`,`cot θ = ${val(q.cot)}; sec θ = ${val(q.sec)}; cosec θ = ${val(q.cosec)}`,`sin² θ + cos² θ = ${fmt(q.sin*q.sin+q.cos*q.cos)}`],['At 0° or 90°, zero denominators make some ratios undefined; never divide by zero.','0° या 90° पर शून्य हर वाले कुछ अनुपात अपरिभाषित हैं; शून्य से भाग न दें।']);return}
 if(this.id===9){let theta=m==='eyeheight'?45:[30,45,60][v-1],q=trig(theta),eye=m==='eyeheight'?v:0,d=m==='height'?this.d:m==='depression'?12/q.tan:10,H=m==='depression'?12:eye+d*q.tan,fit=Math.min(8/d,5.2/H),a=[-4,-2+eye*fit],b=[-4+d*fit,-2],top=[b[0],-2+H*fit];this.line([-5,-2],[6,-2],'axis');this.line(b,top,'shape',{'stroke-width':5});this.line(a,top,'gold');this.line(a,[b[0],a[1]],'shape',{'stroke-dasharray':'5 5'});if(m==='depression')this.line(top,[-4,top[1]],'shape',{'stroke-dasharray':'5 5'});this.mark(a,s('Observer','प्रेक्षक'));this.text([b[0]+.3,(top[1]-2)/2],`${fmt(H)} m`);this.text([-4+d*fit/2,-2.6],`${fmt(d)} m`);this.report([`θ = ${theta}°; d = ${fmt(d)} m`,m==='depression'?`d = H / tan θ = 12 / ${fmt(q.tan)} = ${fmt(d)} m`:`H = h_eye + d tan θ = ${eye} + ${d} × ${fmt(q.tan)} = ${fmt(H)} m`,m==='depression'?s('Angle of depression equals angle of elevation between parallel horizontals.','समांतर क्षैतिज रेखाओं के बीच अवनमन कोण उन्नयन कोण के बराबर है।'):s('The angle is measured from the horizontal, not from the vertical tower.','कोण क्षैतिज से मापा जाता है, ऊर्ध्वाधर मीनार से नहीं।')]);return}
 if(this.id===10){let O=[-1,0],r=2;this.circle(O,r,'shape');if(m==='perpendicular'){let a=rad(v),T=[O[0]+r*Math.cos(a),r*Math.sin(a)],u=[-Math.sin(a),Math.cos(a)];this.line(O,T,'gold');this.line([T[0]-3*u[0],T[1]-3*u[1]],[T[0]+3*u[0],T[1]+3*u[1]],'shape');this.mark(T,'T');this.report([`θ = ${v}°; OT = 2`,s('Radius–tangent angle = 90°','त्रिज्या–स्पर्श रेखा कोण = 90°'),`(cos θ, sin θ) · (−sin θ, cos θ) = 0`]);return}let d=v,P=[O[0]+d,0],q=tangents(d,r);this.mark(O,'O');this.mark(P,'P');if(q.count===1)this.line([P[0],-3],[P[0],3],'gold');if(q.count===2){for(let sign of[-1,1]){let T=[O[0]+r*r/d,sign*r*Math.sqrt(d*d-r*r)/d];this.line(P,T,'gold');this.line(O,T);this.mark(T,sign>0?'A':'B')}}this.report([`OP = ${d}; r = 2`,`${s('Number of tangents','स्पर्श रेखाओं की संख्या')} = ${q.count}`,q.length===null?s('Inside: no real tangent from P.','भीतर: P से कोई वास्तविक स्पर्श रेखा नहीं।'):`PA = PB = √(OP² − r²) = ${fmt(q.length)}`],['For an external point, right triangles OAP and OBP are congruent; hence PA = PB.','बाह्य बिंदु के लिए समकोण त्रिभुज OAP और OBP सर्वांगसम हैं; इसलिए PA = PB।']);return}
 if(this.id===11){let r=m==='sector'?this.r:3,theta=m==='ring'?360:v;if(m==='ring'){this.circle([0,0],4,'shape',{fill:'#78d5bc'});this.circle([0,0],v,'shape',{fill:'#163f35'});this.report([`R = 4 cm; r = ${v} cm`,`A = π(R² − r²) = π(16 − ${fmt(v*v)}) = ${fmt(Math.PI*(16-v*v))} cm²`]);return}let q=sector(r,theta),pts=Array.from({length:Math.max(2,Math.ceil(theta/4)+1)},(_,i)=>{let a=rad(theta*i/Math.max(1,Math.ceil(theta/4)));return[r*Math.cos(a),r*Math.sin(a)]});this.circle([0,0],r,'shape');if(m==='segment')this.path(pts,'gold',true,{fill:'#f0c77555'});else this.path([[0,0],...pts],'gold',true,{fill:'#f0c77555'});this.line([0,0],pts[0]);this.line([0,0],pts.at(-1));this.text([.3,.3],`${theta}°`);this.report([`r = ${r} cm; θ = ${theta}°`,`Sector = θ/360 × πr² = ${fmt(q.area)} cm²`,`Arc = θ/360 × 2πr = ${fmt(q.arc)} cm`,...(m==='segment'?[`Triangle = ½r² sin θ = ${fmt(q.triangle)} cm²`,`Minor segment = sector − triangle = ${fmt(q.segment)} cm²`]:[])],['The angle is in degrees; segment and sector are different regions.','कोण अंश में है; वृत्तखंड और त्रिज्यखंड अलग क्षेत्र हैं।']);return}
 }
}
